custom_qss:
/* ============================================================
   EMBERLINE — red copper & deep rose on near-black espresso.
   Warm, hot, not muddy. Gradient-forward but NOT the old diagonal-
   clash mess: asymmetric vertical metal falls + a red-copper->rose
   sweep on interactive fills. UI pushed hard on STRUCTURE: icon
   sizing, real dividers, spacing, letter-spacing, weights, corner
   radii, a serif header face. One hue family, redder than Sienna.
   ============================================================ */

/* ---------- base type ---------- */
* {
    font-family: Segoe UI, Calibri, Ubuntu, sans-serif;
    color: #f2e2d6;
}
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent;
    border: none;
}

/* ---------- window: asymmetric vertical metal fall ---------- */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #1e120c, stop:0.4 #1c110c, stop:0.75 #120b08, stop:1 #0e0806) !important;
    border-top: 2px solid #6e2c12;
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #1e120c, stop:1 #120b08) !important;
    border: 1px solid #331d13;
    border-top: 2px solid #d9622e;
}

/* ---------- menubar: flat strip, copper active ---------- */
QMenuBar {
    background: #150d09 !important;
    border-bottom: 1px solid #331d13;
    padding: 3px 0;
}
QMenuBar::item {
    background: transparent;
    color: #c8a48c;
    padding: 5px 12px;
    font-size: 12px;
    letter-spacing: 0.3px;
}
QMenuBar::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #2a1810, stop:1 #1c110c) !important;
    color: #f58a4e;
    border-bottom: 2px solid #d9622e;
}

/* ---------- popup menus ---------- */
QMenu {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #22140e, stop:1 #150d09) !important;
    border: 1px solid #4e2c1a;
    border-top: 2px solid #6e2c12;
    padding: 5px;
    font-size: 12px;
}
QMenu::item {
    padding: 7px 30px 7px 16px;
    border-radius: 3px;
    color: #f2e2d6;
    background: transparent;
}
QMenu::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #d9622e, stop:1 #661c17) !important;
    color: #ffffff;
}
QMenu::item:disabled {
    color: #523628;
}
QMenu::separator {
    height: 1px;
    background: #331d13;
    margin: 6px 12px;
}
QMenu::indicator {
    width: 14px;
    height: 14px;
    margin-left: 6px;
}

/* ---------- toolbar: flat, copper active ---------- */
QToolBar {
    background: #150d09 !important;
    border-bottom: 1px solid #331d13;
    spacing: 5px;
    padding: 5px;
}
QToolBar::separator {
    background: #331d13;
    width: 1px;
    margin: 6px 5px;
}
QToolBar::handle {
    background: #4e2c1a;
    width: 10px;
    border-radius: 5px;
}
QToolBar QToolButton {
    background: transparent;
    border: 1px solid transparent;
    border-radius: 4px;
    padding: 6px 10px;
    color: #c8a48c;
    font-size: 12px;
}
QToolBar QToolButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #2a1810, stop:1 #1c110c) !important;
    border: 1px solid #4e2c1a;
    color: #f58a4e;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #d9622e, stop:1 #6e2c12) !important;
    border: 1px solid #d9622e;
    color: #ffffff;
}

/* ---------- buttons: metal gradient, red-copper->rose sweep on hover ---------- */
QPushButton {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #26160e, stop:0.5 #1c110c, stop:1 #150d09) !important;
    border: 1px solid #331d13;
    border-radius: 5px;
    padding: 7px 20px;
    color: #f2e2d6;
    font-size: 12px;
    font-weight: 500;
}
QPushButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #d9622e, stop:0.5 #f58a4e, stop:1 #c8443a) !important;
    border: 1px solid #f58a4e;
    color: #1a0e08;
}
QPushButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #6e2c12, stop:1 #661c17) !important;
    color: #f58a4e;
}
QPushButton:checked {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #6e2c12, stop:1 #1c110c) !important;
    border: 1px solid #d9622e;
    color: #f58a4e;
}
QPushButton:default {
    border: 1px solid #d9622e;
}
QPushButton:disabled {
    color: #523628;
    border: 1px solid #331d13;
}
QPushButton:focus {
    outline: none;
}

/* ---------- inputs: recessed, mono, copper focus ---------- */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: #0c0705 !important;
    border: 1px solid #331d13;
    border-radius: 4px;
    padding: 6px 9px;
    color: #f2e2d6;
    font-family: Cascadia Code, Consolas, monospace;
    font-size: 12px;
    selection-background-color: #6e2c12;
    selection-color: #f2e2d6;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus,
QTextEdit:focus, QPlainTextEdit:focus {
    border: 1px solid #d9622e;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled {
    color: #523628;
}
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent;
    border: none;
    width: 16px;
}

QComboBox {
    background: #0c0705 !important;
    border: 1px solid #331d13;
    border-radius: 4px;
    padding: 6px 9px;
    color: #f2e2d6;
    font-size: 12px;
}
QComboBox:hover {
    border: 1px solid #4e2c1a;
}
QComboBox:focus {
    border: 1px solid #d9622e;
}
QComboBox::drop-down {
    border: none;
    background: transparent;
    width: 18px;
}
QComboBox QAbstractItemView {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #22140e, stop:1 #150d09) !important;
    border: 1px solid #4e2c1a;
    border-top: 2px solid #6e2c12;
    selection-background-color: #2a1810;
    selection-color: #f58a4e;
    outline: none;
}
QComboBox:disabled {
    color: #523628;
}

/* ---------- checkboxes: copper check ---------- */
QCheckBox, QRadioButton {
    background: transparent;
    color: #f2e2d6;
    spacing: 8px;
    font-size: 12px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 15px;
    height: 15px;
    background: #0c0705;
    border: 1px solid #4e2c1a;
    border-radius: 3px;
}
QRadioButton::indicator {
    border-radius: 8px;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover {
    border: 1px solid #d9622e;
}
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #d9622e, stop:1 #6e2c12) !important;
    border: 1px solid #d9622e;
}

/* ---------- tabs: copper underline, serif selected label ---------- */
QTabBar::tab {
    background: transparent;
    color: #8a5f49;
    padding: 9px 18px;
    border: none;
    border-bottom: 2px solid transparent;
    font-size: 12px;
    letter-spacing: 0.5px;
}
QTabBar::tab:hover {
    color: #f2e2d6;
}
QTabBar::tab:selected {
    color: #f58a4e;
    border-bottom: 2px solid #d9622e;
    font-family: Georgia, Georgia, serif;
    font-weight: 700;
}
QTabWidget::pane {
    border: none;
    border-top: 1px solid #331d13;
    background: #120b08;
}

/* ---------- docks: metal gradient, copper title rule ---------- */
QDockWidget {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #1e120c, stop:0.6 #1c110c, stop:1 #150d09) !important;
    border: 1px solid #331d13;
}
QDockWidget::title {
    background: #150d09 !important;
    border-bottom: 1px solid #331d13;
    border-left: 3px solid #6e2c12;
    padding: 7px 11px;
    color: #c8a48c;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.5px;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent;
    border: none;
    border-radius: 3px;
    padding: 3px;
    icon-size: 14px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background: #2a1810;
}

/* ---------- group boxes: serif copper label, left tick ---------- */
QGroupBox {
    background: transparent;
    border: 1px solid #331d13;
    border-left: 3px solid #6e2c12;
    border-radius: 5px;
    margin-top: 13px;
    padding-top: 11px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.2px;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 9px;
    color: #d9622e;
    font-family: Georgia, Georgia, serif;
    font-weight: 700;
    background: #120b08;
}

/* ---------- item views ---------- */
QAbstractItemView {
    background: #0c0705 !important;
    border: 1px solid #331d13;
    border-radius: 5px;
    alternate-background-color: #150d09;
    outline: none;
    selection-background-color: #2a1810;
    selection-color: #f58a4e;
    font-size: 12px;
}
QAbstractItemView::item {
    padding: 6px 9px;
    border: none;
    color: #f2e2d6;
}
QAbstractItemView::item:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #2a1810, stop:1 #1c110c) !important;
}
QAbstractItemView::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #2a1810, stop:1 #0c0705) !important;
    color: #f58a4e;
    border-left: 3px solid #d9622e;
}
QAbstractItemView::item:selected:!active {
    background: #150d09;
    color: #c8a48c;
}
QTreeView::branch {
    background: transparent;
}
QHeaderView::section {
    background: #150d09 !important;
    border: none;
    border-bottom: 1px solid #4e2c1a;
    border-right: 1px solid #331d13;
    padding: 7px 11px;
    color: #8a5f49;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1px;
}

/* ---------- scrollbars: thin, copper handle ---------- */
QScrollBar:vertical {
    background: #0c0705;
    width: 11px;
    margin: 0;
    border: none;
}
QScrollBar::handle:vertical {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #4e2c1a, stop:1 #331d13) !important;
    border-radius: 5px;
    min-height: 32px;
}
QScrollBar::handle:vertical:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #d9622e, stop:1 #6e2c12) !important;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0;
    border: none;
    background: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: none;
}
QScrollBar:horizontal {
    background: #0c0705;
    height: 11px;
    margin: 0;
    border: none;
}
QScrollBar::handle:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #4e2c1a, stop:1 #331d13) !important;
    border-radius: 5px;
    min-width: 32px;
}
QScrollBar::handle:horizontal:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #d9622e, stop:1 #6e2c12) !important;
}
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0;
    border: none;
    background: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: none;
}
QScrollBar::corner {
    background: none;
}

/* ---------- sliders: red-copper->rose fill, copper handle ---------- */
QSlider::groove:horizontal {
    background: #0c0705;
    border: 1px solid #331d13;
    height: 5px;
    border-radius: 3px;
}
QSlider::sub-page:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #d9622e, stop:1 #c8443a) !important;
    border-radius: 2px;
}
QSlider::add-page:horizontal {
    background: #0c0705;
    border-radius: 2px;
}
QSlider::handle:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #f58a4e, stop:1 #d9622e) !important;
    width: 14px;
    height: 14px;
    margin: -6px 0;
    border: 1px solid #d9622e;
    border-radius: 7px;
}
QSlider::handle:horizontal:hover {
    background: #e8705f;
    border: 1px solid #c8443a;
}
QSlider::groove:vertical {
    background: #0c0705;
    border: 1px solid #331d13;
    width: 5px;
    border-radius: 3px;
}
QSlider::sub-page:vertical {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #d9622e, stop:1 #c8443a) !important;
    border-radius: 2px;
}
QSlider::handle:vertical {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #f58a4e, stop:1 #d9622e) !important;
    width: 14px;
    height: 14px;
    margin: 0 -6px;
    border: 1px solid #d9622e;
    border-radius: 7px;
}

/* ---------- progress: red-copper->rose sweep ---------- */
QProgressBar {
    background: #0c0705;
    border: 1px solid #331d13;
    border-radius: 3px;
    text-align: center;
    color: #c8a48c;
    font-size: 11px;
    min-height: 15px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #d9622e, stop:1 #c8443a) !important;
    border-radius: 2px;
}

/* ---------- statusbar: flat ---------- */
QStatusBar {
    background: #150d09 !important;
    border-top: 1px solid #331d13;
    color: #8a5f49;
    font-size: 11px;
}
QStatusBar::item {
    border: none;
}
QStatusBar QLabel {
    color: #8a5f49;
    font-size: 11px;
}

/* ---------- tooltip ---------- */
QToolTip {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #22140e, stop:1 #150d09) !important;
    border: 1px solid #4e2c1a;
    border-top: 2px solid #6e2c12;
    border-radius: 4px;
    padding: 7px 11px;
    color: #f2e2d6;
    font-size: 12px;
}

/* ---------- splitters ---------- */
QSplitter::handle {
    background: #331d13;
}
QSplitter::handle:hover {
    background: #6e2c12;
}

/* ---------- secondary list widgets ---------- */
QListView, QListWidget, QTreeWidget, QTableWidget {
    background: #0c0705 !important;
    border: 1px solid #331d13;
    border-radius: 5px;
    outline: none;
}
QTableCornerButton::section {
    background: #150d09;
    border: 1px solid #331d13;
}
